const testFrontendOrigin = "https://frontend.example.test"

// Generated by Codex and not thoroughly checked for correctness.
func TestRouterAssemblyPreservesRoutesAndCORS(t *testing.T) {
	config := newRouterMockConfig(t)
	router, err := app.NewRouter(config, nil)
	if err != nil {
		t.Fatal(err)
	}
	for _, testCase := range []struct {
		name, method, path, origin string
		status                     int
	}{
		{"liveness needs no database", http.MethodGet, "/health/live", "", http.StatusOK},
		{"protected routes require authentication", http.MethodGet, "/api/v1/user/profile", "", http.StatusUnauthorized},
		{"unversioned routes remain absent", http.MethodGet, "/api/user/profile", "", http.StatusNotFound},
		{"callback rejects missing state before provider calls", http.MethodGet, "/api/v1/auth/github/callback", "", http.StatusBadRequest},
		{"allowed browser origin receives CORS headers", http.MethodGet, "/health/live", testFrontendOrigin, http.StatusOK},
		{"unlisted browser origin is rejected", http.MethodGet, "/health/live", "https://unlisted.example.test", http.StatusForbidden},
		{"authorization preflight is accepted", http.MethodOptions, "/api/v1/user/profile", testFrontendOrigin, http.StatusNoContent},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			request := httptest.NewRequest(testCase.method, testCase.path, nil)
			request.Header.Set("Origin", testCase.origin)
			if testCase.method == http.MethodOptions {
				request.Header.Set("Access-Control-Request-Method", http.MethodGet)
				request.Header.Set("Access-Control-Request-Headers", "Authorization, Content-Type")
			}
			response := httptest.NewRecorder()
			router.ServeHTTP(response, request)
			if response.Code != testCase.status {
				t.Fatalf("status = %d, want %d", response.Code, testCase.status)
			}
			if testCase.origin == testFrontendOrigin {
				if response.Header().Get("Access-Control-Allow-Origin") != testFrontendOrigin || response.Header().Get("Access-Control-Allow-Credentials") != "true" {
					t.Fatal("router did not apply credentialed CORS configuration")
				}
				if testCase.method != http.MethodOptions && response.Header().Get("Access-Control-Expose-Headers") != "Retry-After" {
					t.Fatal("router did not expose rate-limit retry headers")
				}
			}
		})
	}

	response := httptest.NewRecorder()
	router.ServeHTTP(response, httptest.NewRequest(http.MethodGet, "/api/v1/auth/github/login", nil))
	location, err := url.Parse(response.Header().Get("Location"))
	if err != nil {
		t.Fatal(err)
	}
	if response.Code != http.StatusTemporaryRedirect || location.Host != "github.com" || location.Query().Get("client_id") != config.GitHubClientID || location.Query().Get("redirect_uri") != config.GitHubRedirectURL || location.Query().Get("state") == "" {
		t.Fatalf("OAuth configuration not wired: status = %d, location = %v", response.Code, location)
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestRouterAssemblyRejectsInvalidSettings(t *testing.T) {
	config := newRouterMockConfig(t)
	for _, testCase := range []struct {
		name   string
		change func(*configs.Config)
		error  string
	}{
		{"general rate", func(config *configs.Config) { config.APIRatePerMinute = 0 }, "invalid rate limits"},
		{"write rate", func(config *configs.Config) { config.WriteRatePerMinute = 0 }, "invalid rate limits"},
		{"authentication rate", func(config *configs.Config) { config.AuthRatePerMinute = 0 }, "invalid rate limits"},
		{"Codeforces cooldown", func(config *configs.Config) { config.CodeforcesCooldown = 0 }, "invalid rate limits"},
		{"trusted proxy", func(config *configs.Config) { config.TrustedProxies = []string{"invalid-proxy"} }, "invalid trusted proxies"},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			changed := config
			testCase.change(&changed)
			router, err := app.NewRouter(changed, nil)
			if router != nil || err == nil || !strings.Contains(err.Error(), testCase.error) {
				t.Fatalf("router = %v, error = %v; want %q", router, err, testCase.error)
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestRouterAssemblySharesCallbackAllowanceAcrossAliases(t *testing.T) {
	config := newRouterMockConfig(t)
	router, err := app.NewRouter(config, nil)
	if err != nil {
		t.Fatal(err)
	}
	for attempt := range 11 {
		path := "/api/v1/auth/github/callback"
		if attempt%2 == 0 {
			path = "/v1/auth/github/callback"
		}
		response := httptest.NewRecorder()
		router.ServeHTTP(response, httptest.NewRequest(http.MethodGet, path, nil))
		want := http.StatusBadRequest
		if attempt == 10 {
			want = http.StatusTooManyRequests
			if response.Header().Get("Retry-After") == "" {
				t.Fatal("rate limit did not provide a retry delay")
			}
		}
		if response.Code != want {
			t.Fatalf("attempt %d: status = %d, want %d", attempt, response.Code, want)
		}
	}
}

func newRouterMockConfig(t *testing.T) configs.Config {
	t.Helper()
	gin.SetMode(gin.TestMode)
	previousOutput, previousErrorOutput := gin.DefaultWriter, gin.DefaultErrorWriter
	gin.DefaultWriter, gin.DefaultErrorWriter = io.Discard, io.Discard
	t.Cleanup(func() {
		gin.DefaultWriter, gin.DefaultErrorWriter = previousOutput, previousErrorOutput
	})
	return configs.Config{
		GitHubClientID: "router-client", GitHubClientSecret: "router-secret",
		GitHubRedirectURL:  "https://frontend.example.test/callback/auth-gh",
		CORSAllowedOrigins: []string{testFrontendOrigin},
		ExternalAPITimeout: time.Second, DatabaseTimeout: time.Second,
		APIRatePerMinute: 60, WriteRatePerMinute: 30, AuthRatePerMinute: 1,
		CodeforcesCooldown: time.Minute,
	}
}
